import{_ as s,o as t,c as o,a3 as a}from"./chunks/framework.DH50UWNB.js";const g=JSON.parse('{"title":"Versions and tags","description":"","frontmatter":{},"headers":[],"relativePath":"use/versions.md","filePath":"use/versions.md"}'),i={name:"use/versions.md"};function n(r,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="versions-and-tags" tabindex="-1">Versions and tags <a class="header-anchor" href="#versions-and-tags" aria-label="Permalink to &quot;Versions and tags&quot;">​</a></h1><p>A version in Wake is a git tag of your repository: <code>v&lt;major&gt;.&lt;minor&gt;.&lt;patch&gt;</code>, with an optional prerelease such as <code>v1.0.0-rc.1</code>. Wake reads the tags when it syncs; you never create versions in the web app.</p><h2 id="release-a-version" tabindex="-1">Release a version <a class="header-anchor" href="#release-a-version" aria-label="Permalink to &quot;Release a version&quot;">​</a></h2><p>A tag releases the tasks done in its tagged commit that no lower tag (in semver order) already released. To release one:</p><ol><li>Check off the finished tasks in your plan and commit.</li><li>Tag the commit: <code>git tag -a v0.1.0 -m &quot;v0.1.0&quot;</code>.</li><li>Run <code>wake sync</code>, or let the next agent session start sync it.</li></ol><p>The version appears in <strong>Versions</strong> with its tasks, grouped by phase with their commits, and <strong>Tracking</strong> names it as the newest version. A tag deleted locally is marked removed on the next sync.</p><p>A shallow clone sends no tags, so the recorded versions stay as they are.</p><p>A <a href="/wake-dist/docs/agents/milestones">milestone</a> can name the version tag that delivers it.</p><h2 id="links-to-your-git-host" tabindex="-1">Links to your git host <a class="header-anchor" href="#links-to-your-git-host" aria-label="Permalink to &quot;Links to your git host&quot;">​</a></h2><p>The <strong>View tag</strong> link of a version opens its tag on the repository&#39;s git host. <code>wake sync</code> recognizes these hosts from the <code>origin</code> remote, with no other tool:</p><ul><li>GitHub, and GitHub Enterprise hosts named <code>github.*</code>;</li><li>GitLab: gitlab.com and hosts whose name contains <code>gitlab</code>;</li><li>Bitbucket Cloud;</li><li>Azure DevOps: the cloud service, <code>visualstudio.com</code> and Azure DevOps Server.</li></ul><p>For another host, add its provider as <code>gitHost</code> (<code>github</code>, <code>gitlab</code>, <code>bitbucket</code> or <code>azure-devops</code>) to <code>.wake/config.json</code> and commit it:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gitHost&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gitlab&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Without <code>origin</code>, with an <code>http:</code> remote or on an unknown host, versions have no link.</p>',14)])])}const u=s(i,[["render",n]]);export{g as __pageData,u as default};
